    for (int i = 0; i < 5; i++) {
        pooledObj = pool.borrowObject(key);
    }
    // abandon checked out instances and let evictor start
    Thread.sleep(1000);
    if (!pool.getKeys().contains(key)) {
        // Wait a little more.
        Thread.sleep(1000);
    }
    if (!pool.getKeys().contains(key)) {
        // Wait a little more.
