/**
 * Simplest example of recovery from factory outage.
 * A thread gets into parked wait on the deque when there is capacity to create,
 * but
 * creates are failing due to factory outage. Verify that the borrower is served
 * once the factory is back online.
 */
@Test
@Timeout(value = 1000, unit = TimeUnit.MILLISECONDS)
void testLivenessOnTransientFactoryFailure() throws InterruptedException {
    final DisconnectingWaiterFactory<String> factory = new DisconnectingWaiterFactory<>(DisconnectingWaiterFactory.DEFAULT_DISCONNECTED_CREATE_ACTION, DisconnectingWaiterFactory.DEFAULT_DISCONNECTED_LIFECYCLE_ACTION, // all instances fail validation
    obj -> false);
    final AtomicBoolean failed = new AtomicBoolean();
    final ResilientPooledObjectFactory<Waiter, IllegalStateException> resilientFactory = new ResilientPooledObjectFactory<>(factory, 10, Duration.ofMillis(20), Duration.ofMinutes(10), Duration.ofMillis(20));
    try (GenericObjectPool<Waiter, IllegalStateException> pool = new GenericObjectPool<>(resilientFactory)) {
        resilientFactory.setPool(pool);
        resilientFactory.startMonitor();
        pool.setMaxWait(Duration.ofMillis(100));
        pool.setTestOnReturn(true);
        pool.setMaxTotal(1);
        final Waiter w = pool.borrowObject();
        final Thread t = new Thread(() -> {
            try {
                pool.borrowObject();
            } catch (final NoSuchElementException e) {
                failed.set(true);
            }
        });
        Thread.sleep(10);
        t.start();
        // t is blocked waiting on the deque
        Thread.sleep(10);
        factory.disconnect();
        // validation fails, so no return
        pool.returnObject(w);
        Thread.sleep(10);
        factory.connect();
        // Borrower should be able to be served now
        t.join();
    }
    if (failed.get()) {
        fail("Borrower timed out waiting for an instance");
    }
}

