@Test
void testContextClassLoader() throws Exception {
    final ClassLoader savedClassloader = Thread.currentThread().getContextClassLoader();
    try (CustomClassLoader cl1 = new CustomClassLoader(1)) {
        Thread.currentThread().setContextClassLoader(cl1);
        final CustomClassLoaderObjectFactory factory1 = new CustomClassLoaderObjectFactory(1);
        try (GenericObjectPool<URL, IllegalStateException> pool1 = new GenericObjectPool<>(factory1)) {
            pool1.setMinIdle(1);
            pool1.setDurationBetweenEvictionRuns(Duration.ofMillis(100));
            int counter = 0;
            while (counter < 50 && pool1.getNumIdle() != 1) {
                Thread.sleep(100);
                counter++;
            }
            assertEquals(1, pool1.getNumIdle(), "Wrong number of idle objects in pool1");
            try (CustomClassLoader cl2 = new CustomClassLoader(2)) {
                Thread.currentThread().setContextClassLoader(cl2);
                final CustomClassLoaderObjectFactory factory2 = new CustomClassLoaderObjectFactory(2);
                try (GenericObjectPool<URL, IllegalStateException> pool2 = new GenericObjectPool<>(factory2)) {
                    pool2.setMinIdle(1);
                    pool2.addObject();
                    assertEquals(1, pool2.getNumIdle(), "Wrong number of idle objects in pool2");
                    pool2.clear();
                    pool2.setDurationBetweenEvictionRuns(Duration.ofMillis(100));
                    counter = 0;
                    while (counter < 50 && pool2.getNumIdle() != 1) {
                        Thread.sleep(100);
                        counter++;
                    }
                    assertEquals(1, pool2.getNumIdle(), "Wrong number of  idle objects in pool2");
                }
            }
        }
    } finally {
        Thread.currentThread().setContextClassLoader(savedClassloader);
    }
}

@Test
@Timeout(value = 10_000, unit = TimeUnit.MILLISECONDS)
void testBorrowObjectStuck() {
    final SingleObjectFactory factory = new SingleObjectFactory();
    final GenericObjectPoolConfig<Object> config = new GenericObjectPoolConfig<>();
    config.setMaxIdle(1);
    config.setMaxTotal(1);
    config.setBlockWhenExhausted(true);
    config.setMinIdle(0);
    config.setTestOnBorrow(true);
    config.setTestOnReturn(true);
    config.setTestWhileIdle(false);
    config.setDurationBetweenEvictionRuns(NEG_ONE_DURATION);
    config.setMinEvictableIdleDuration(NEG_ONE_DURATION);
    config.setSoftMinEvictableIdleDuration(NEG_ONE_DURATION);
    config.setMaxWait(NEG_ONE_DURATION);
    try (GenericObjectPool<Object, Exception> pool = new GenericObjectPool<>(factory, config)) {
        final AtomicBoolean failed = new AtomicBoolean();
        final CountDownLatch barrier = new CountDownLatch(1);
        final Thread thread1 = new Thread(new WinnerRunnable(pool, barrier, failed));
        thread1.start();
        // wait for object to be created
        while (!factory.created.get()) {
            Waiter.sleepQuietly(5);
        }
        // now borrow
        barrier.countDown();
        try {
            println("try borrow in main thread");
            final Object o = pool.borrowObject();
            println("Success borrow in main thread " + o);
        } catch (final Exception e) {
            e.printStackTrace();
        }
        assertFalse(failed.get());
    }
}

