@Test
void testNulls() throws Exception {
    final FailingFactory ff = new FailingFactory();
    // Make the factory fail with exception immediately on make
    ff.setSilentFail(true);
    final ResilientPooledObjectFactory<String, Exception> rf = new ResilientPooledObjectFactory<>(ff, 5, Duration.ofMillis(50), Duration.ofMinutes(10), Duration.ofMillis(50));
    // Create a pool with a max size of 2, using the resilient factory
    final GenericObjectPool<String, Exception> pool = new GenericObjectPool<>(rf);
    pool.setMaxTotal(2);
    pool.setBlockWhenExhausted(true);
    pool.setTestOnReturn(true);
    // Tell the factory what pool it is attached to (a little awkward)
    rf.setPool(pool);
    // 20ms monitor interval
    rf.startMonitor(Duration.ofMillis(20));
    // Exhaust the pool
    final String s1 = pool.borrowObject();
    final String s2 = pool.borrowObject();
    ff.crash();
    // Start two borrowers that will block waiting
    new Thread() {

        @Override
        public void run() {
            try {
                final String s = pool.borrowObject();
                pool.returnObject(s);
            } catch (final Exception e) {
            }
        }
    }.start();
    new Thread() {

        @Override
        public void run() {
            try {
                final String s = pool.borrowObject();
                pool.returnObject(s);
            } catch (final Exception e) {
            }
        }
    }.start();
    // Return borrowed objects - validation will fail
    // Wait for the borrowers to get in the queue
    try {
        Thread.sleep(50);
    } catch (final InterruptedException e) {
    }
    pool.returnObject(s1);
    pool.returnObject(s2);
    assertEquals(0, pool.getNumIdle());
    assertTrue(pool.getNumWaiters() > 0);
    // Wait for the monitor to pick up the failed create which should happen on
    // validation destroy
    try {
        Thread.sleep(200);
    } catch (final InterruptedException e) {
    }
    assertFalse(rf.isUp());
    // Restart the factory
    ff.recover();
    // Wait for the adder to succeed
    try {
        Thread.sleep(200);
    } catch (final InterruptedException e) {
    }
    // Pool should have no waiters
    assertEquals(0, pool.getNumWaiters());
    pool.close();
    // Wait for monitor to run
    try {
        Thread.sleep(200);
    } catch (final InterruptedException e) {
    }
    // Monitor and adder should be stopped by pool close
    assertFalse(rf.isAdderRunning());
    assertFalse(rf.isMonitorRunning());
}

@Test
void testTransientFailure() throws Exception {
    final FailingFactory ff = new FailingFactory();
    // Make the factory fail with exception immediately on make
    ff.setHang(false);
    ff.setSilentFail(false);
    final ResilientPooledObjectFactory<String, Exception> rf = new ResilientPooledObjectFactory<>(ff, 5, Duration.ofMillis(100), Duration.ofMinutes(10), Duration.ofMillis(100));
    // Create a pool with a max size of 2, using the resilient factory
    final GenericObjectPool<String, Exception> pool = new GenericObjectPool<>(rf);
    pool.setMaxTotal(2);
    pool.setBlockWhenExhausted(true);
    pool.setTestOnReturn(true);
    // Tell the factory what pool it is attached to (a little awkward)
    rf.setPool(pool);
    // 20ms monitor interval
    rf.startMonitor(Duration.ofMillis(20));
    // Base factory is up
    assertTrue(rf.isUp());
    // Check out a couple of objects
    final String s1 = pool.borrowObject();
    final String s2 = pool.borrowObject();
    // Start a borrower that will wait
    new Thread() {

        @Override
        public void run() {
            try {
                pool.borrowObject();
            } catch (final Exception e) {
            }
        }
    }.start();
    // Wait for the borrower to join wait queue
    try {
        Thread.sleep(200);
    } catch (final InterruptedException e) {
    }
    // Crash the base factory
    ff.crash();
    // Resilient factory does not know the base factory is down until a make is
    // attempted
    assertTrue(rf.isUp());
    assertEquals(1, pool.getNumWaiters());
    pool.returnObject(s1);
    pool.returnObject(s2);
    assertEquals(0, pool.getNumIdle());
    assertEquals(1, pool.getNumWaiters());
    // Wait for the monitor to pick up the failed create which should happen on
    // validation destroy
    try {
        Thread.sleep(100);
    } catch (final InterruptedException e) {
    }
    assertFalse(rf.isUp());
    // Adder should be running, but failing
    assertTrue(rf.isAdderRunning());
    // Pool should have one take waiter
    assertEquals(1, pool.getNumWaiters());
    // Restart the factory
    ff.recover();
    // Wait for the adder to succeed
    try {
        Thread.sleep(100);
    } catch (final InterruptedException e) {
    }
    // Pool should have no waiters
    assertTrue(pool.getNumWaiters() == 0);
    // Add 5 objects to clear the rf log
    // First have to expand the pool
    pool.setMaxTotal(10);
    for (int i = 0; i < 5; i++) {
        pool.addObject();
    }
    // Wait for monitor to run
    try {
        Thread.sleep(200);
    } catch (final InterruptedException e) {
    }
    // rf should be up now
    assertTrue(rf.isUp());
    // Adder should be stopped
    assertFalse(rf.isAdderRunning());
    pool.close();
    rf.stopMonitor();
}

@Test
void testOutOfMemory() throws Exception {
    pool = new SoftReferenceObjectPool<>(new SmallPoolableObjectFactory());
    String obj = pool.borrowObject();
    assertEquals("1", obj);
    pool.returnObject(obj);
    obj = null;
    assertEquals(1, pool.getNumIdle());
    final List<byte[]> garbage = new LinkedList<>();
    final Runtime runtime = Runtime.getRuntime();
    while (pool.getNumIdle() > 0) {
        try {
            long freeMemory = runtime.freeMemory();
            if (freeMemory > Integer.MAX_VALUE) {
                freeMemory = Integer.MAX_VALUE;
            }
            garbage.add(new byte[Math.min(1024 * 1024, (int) freeMemory / 2)]);
        } catch (final OutOfMemoryError oome) {
            System.gc();
        }
        System.gc();
    }
    garbage.clear();
    System.gc();
    obj = pool.borrowObject();
    assertEquals("2", obj);
    pool.returnObject(obj);
    obj = null;
    assertEquals(1, pool.getNumIdle());
}

