/**
 * Default destroy does nothing to underlying AtomicInt, ABANDONED mode increments the value. Verify that destroy with no mode does default, destroy with
 * ABANDONED mode increments.
 *
 * @throws RuntimeException May occur in some failure modes
 */
@Test
void testDestroyModes() {
    final PooledObjectFactory<AtomicInteger, RuntimeException> factory = new TestFactory();
    final PooledObject<AtomicInteger> pooledObj = factory.makeObject();
    final AtomicInteger obj = pooledObj.getObject();
    factory.destroyObject(pooledObj);
    assertEquals(0, obj.get());
    factory.destroyObject(pooledObj, DestroyMode.ABANDONED);
    assertEquals(1, obj.get());
}

@Test
void testCheckMinIdleKeyedObjectPool() throws InterruptedException {
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.checkMinIdle(null, new Object(), 1, 1), "PoolUtils.checkMinIdle(KeyedObjectPool,Object,int,long) must not allow null pool.");
    try (@SuppressWarnings("unchecked") KeyedObjectPool<Object, Object, RuntimeException> pool = createProxy(KeyedObjectPool.class, (List<String>) null)) {
        assertThrows(IllegalArgumentException.class, () -> PoolUtils.checkMinIdle(pool, (Object) null, 1, 1), "PoolUtils.checkMinIdle(KeyedObjectPool,Object,int,long) must not accept null keys.");
    }
    try (@SuppressWarnings("unchecked") KeyedObjectPool<Object, Object, RuntimeException> pool = createProxy(KeyedObjectPool.class, (List<String>) null)) {
        assertThrows(IllegalArgumentException.class, () -> PoolUtils.checkMinIdle(pool, new Object(), -1, 1), "PoolUtils.checkMinIdle(KeyedObjectPool,Object,int,long) must not accept negative min idle values.");
    }
    final List<String> calledMethods = new ArrayList<>();
    final Object key = new Object();
    // Test that the minIdle check doesn't add too many idle objects
    @SuppressWarnings("unchecked")
    final KeyedPooledObjectFactory<Object, Object, RuntimeException> kpof = createProxy(KeyedPooledObjectFactory.class, calledMethods);
    try (KeyedObjectPool<Object, Object, RuntimeException> kop = new GenericKeyedObjectPool<>(kpof)) {
        PoolUtils.checkMinIdle(kop, key, 2, 100);
        Thread.sleep(400);
        assertEquals(2, kop.getNumIdle(key));
        assertEquals(2, kop.getNumIdle());
    }
    int makeObjectCount = 0;
    for (final String methodName : calledMethods) {
        if ("makeObject".equals(methodName)) {
            makeObjectCount++;
        }
    }
    assertEquals(2, makeObjectCount, "makeObject should have been called two time");
    // Because this isn't deterministic and you can get false failures, try more than once.
    AssertionFailedError afe = null;
    int triesLeft = 3;
    do {
        afe = null;
        try {
            calledMethods.clear();
            try (@SuppressWarnings("unchecked") KeyedObjectPool<Object, Object, RuntimeException> pool = createProxy(KeyedObjectPool.class, calledMethods)) {
                // checks minIdle immediately
                final TimerTask task = PoolUtils.checkMinIdle(pool, key, 1, CHECK_PERIOD);
                // will check CHECK_COUNT more times.
                Thread.sleep(CHECK_SLEEP_PERIOD);
                task.cancel();
                task.toString();
                final List<String> expectedMethods = new ArrayList<>();
                for (int i = 0; i < CHECK_COUNT; i++) {
                    expectedMethods.add("getNumIdle");
                    expectedMethods.add("addObject");
                }
                expectedMethods.add("toString");
                // may fail because of the thread scheduler
                assertEquals(expectedMethods, calledMethods);
            }
        } catch (final AssertionFailedError e) {
            afe = e;
        }
    } while (--triesLeft > 0 && afe != null);
    if (afe != null) {
        throw afe;
    }
}

