@Test
void testErodingPerKeyKeyedObjectPool() throws InterruptedException {
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool((KeyedObjectPool<Object, Object, RuntimeException>) null, 1f, true), "PoolUtils.erodingPool(KeyedObjectPool) must not allow a null pool.");
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool((KeyedObjectPool<Object, Object, RuntimeException>) null, 0f, true), "PoolUtils.erodingPool(ObjectPool, float, boolean) must not allow a non-positive factor.");
    assertThrows(IllegalArgumentException.class, () -> PoolUtils.erodingPool((KeyedObjectPool<Object, Object, RuntimeException>) null, 1f, true), "PoolUtils.erodingPool(KeyedObjectPool, float, boolean) must not allow a null pool.");
    final List<String> calledMethods = new ArrayList<>();
    final InvocationHandler handler = new MethodCallLogger(calledMethods) {

        @Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
            Object o = super.invoke(proxy, method, args);
            if (o instanceof Integer) {
                // so getNumActive/getNumIdle are not zero.
                o = Integer.valueOf(1);
            }
            return o;
        }
    };
    // If the logic behind PoolUtils.erodingPool changes then this will need to be tweaked.
    // about ~9 seconds until first discard
    final float factor = 0.01f;
    try (@SuppressWarnings("unchecked") KeyedObjectPool<Object, Object, RuntimeException> pool = PoolUtils.erodingPool(createProxy(KeyedObjectPool.class, handler), factor, true)) {
        final List<String> expectedMethods = new ArrayList<>();
        assertEquals(expectedMethods, calledMethods);
        final Object key = "key";
        Object o = pool.borrowObject(key);
        expectedMethods.add("borrowObject");
        assertEquals(expectedMethods, calledMethods);
        pool.returnObject(key, o);
        expectedMethods.add("returnObject");
        assertEquals(expectedMethods, calledMethods);
        for (int i = 0; i < 5; i++) {
            o = pool.borrowObject(key);
            expectedMethods.add("borrowObject");
            Thread.sleep(50);
            pool.returnObject(key, o);
            expectedMethods.add("returnObject");
            assertEquals(expectedMethods, calledMethods);
            expectedMethods.clear();
            calledMethods.clear();
        }
        // 10 seconds
        Thread.sleep(10000);
        o = pool.borrowObject(key);
        expectedMethods.add("borrowObject");
        pool.returnObject(key, o);
        expectedMethods.add("getNumIdle");
        expectedMethods.add("invalidateObject");
        assertEquals(expectedMethods, calledMethods);
        final String expectedToString = "ErodingPerKeyKeyedObjectPool{factor=" + factor + ", keyedPool=null}";
        assertEquals(expectedToString, pool.toString());
    }
}

